"use client";

import { Select as BaseSelect } from "@base-ui/react/select";
import { clsx } from "clsx";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { createContext, useContext } from "react";

import "./select.css";

const SelectLoadingContext = createContext(false);

export type SelectRootProps<Value> = BaseSelect.Root.Props<Value> & {
  loading?: boolean;
};

export function SelectRoot<Value>({ loading = false, readOnly, ...props }: SelectRootProps<Value>) {
  return (
    <SelectLoadingContext value={loading}>
      <BaseSelect.Root {...props} readOnly={loading || readOnly} />
    </SelectLoadingContext>
  );
}

export type SelectTriggerProps = ComponentPropsWithRef<typeof BaseSelect.Trigger> & {
  loading?: boolean;
  size?: "sm" | "md" | "lg";
};

export function SelectTrigger({
  "aria-busy": ariaBusy,
  className,
  loading,
  size = "md",
  ...props
}: SelectTriggerProps) {
  const rootLoading = useContext(SelectLoadingContext);
  const isLoading = loading ?? rootLoading;

  return (
    <BaseSelect.Trigger
      {...props}
      aria-busy={isLoading || ariaBusy || undefined}
      className={clsx("mfd-select__trigger", className)}
      data-size={size}
    />
  );
}

export type SelectValueProps = ComponentPropsWithRef<typeof BaseSelect.Value>;

export function SelectValue(props: SelectValueProps) {
  return <BaseSelect.Value {...props} />;
}

export type SelectIconProps = ComponentPropsWithRef<typeof BaseSelect.Icon> & {
  loading?: boolean;
};

export function SelectIcon({ className, children = "⌄", loading, ...props }: SelectIconProps) {
  const rootLoading = useContext(SelectLoadingContext);
  const isLoading = loading ?? rootLoading;

  return (
    <BaseSelect.Icon {...props} className={clsx("mfd-select__icon", className)}>
      <span aria-hidden="true" className={isLoading ? "mfd-select__spinner" : undefined}>
        {isLoading ? null : children}
      </span>
    </BaseSelect.Icon>
  );
}

export type SelectContentProps = ComponentPropsWithRef<typeof BaseSelect.Popup> & {
  children?: ReactNode;
};

export function SelectContent({ children, className, ...props }: SelectContentProps) {
  return (
    <BaseSelect.Portal>
      <BaseSelect.Positioner className="mfd-select__positioner" sideOffset={4}>
        <BaseSelect.Popup {...props} className={clsx("mfd-select__popup", className)}>
          <BaseSelect.List>{children}</BaseSelect.List>
        </BaseSelect.Popup>
      </BaseSelect.Positioner>
    </BaseSelect.Portal>
  );
}

export type SelectItemProps = ComponentPropsWithRef<typeof BaseSelect.Item>;

export function SelectItem({ children, className, ...props }: SelectItemProps) {
  return (
    <BaseSelect.Item {...props} className={clsx("mfd-select__item", className)}>
      <span className="mfd-select__item-label">{children}</span>
      <BaseSelect.ItemIndicator className="mfd-select__item-indicator">✓</BaseSelect.ItemIndicator>
    </BaseSelect.Item>
  );
}

export type SelectItemIndicatorProps = ComponentPropsWithRef<typeof BaseSelect.ItemIndicator>;

export function SelectItemIndicator(props: SelectItemIndicatorProps) {
  return <BaseSelect.ItemIndicator {...props} />;
}

export type SelectProps = Readonly<{
  Root: typeof SelectRoot;
  Trigger: typeof SelectTrigger;
  Value: typeof SelectValue;
  Icon: typeof SelectIcon;
  Content: typeof SelectContent;
  Item: typeof SelectItem;
  ItemIndicator: typeof SelectItemIndicator;
}>;

export const Select: SelectProps = {
  Root: SelectRoot,
  Trigger: SelectTrigger,
  Value: SelectValue,
  Icon: SelectIcon,
  Content: SelectContent,
  Item: SelectItem,
  ItemIndicator: SelectItemIndicator,
};

.mfd-select__trigger {
  align-items: center;
  background: var(--mfd-color-bg-canvas);
  border: 1px solid var(--mfd-color-border-default);
  border-radius: var(--mfd-radius-control);
  color: var(--mfd-color-text-primary);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  gap: var(--mfd-space-inline-sm);
  justify-content: space-between;
  min-height: max(var(--mfd-size-control-height-md), var(--mfd-size-hit-target-minimum));
  min-width: 10rem;
  padding-inline: var(--mfd-space-inline-md);
  text-align: start;
  touch-action: manipulation;
}

.mfd-select__trigger[data-size="sm"] {
  min-height: max(var(--mfd-size-control-height-sm), var(--mfd-size-hit-target-minimum));
}

.mfd-select__trigger[data-size="lg"] {
  min-height: max(var(--mfd-size-control-height-lg), var(--mfd-size-hit-target-minimum));
}

.mfd-select__trigger:focus-visible {
  border-color: var(--mfd-color-border-focus);
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 2px;
}

.mfd-select__trigger[data-popup-open] {
  border-color: var(--mfd-color-border-focus);
}

.mfd-select__trigger[aria-busy="true"] {
  cursor: wait;
}

.mfd-select__trigger:disabled,
.mfd-select__trigger[aria-readonly="true"] {
  cursor: not-allowed;
  opacity: 0.7;
}

.mfd-select__icon {
  align-items: center;
  color: var(--mfd-color-text-secondary);
  display: inline-flex;
  flex: none;
  font-size: 1.15em;
  line-height: 1;
}

.mfd-select__spinner {
  animation: mfd-select-spin var(--mfd-motion-duration-slow) linear infinite;
  border: 2px solid currentColor;
  border-block-start-color: transparent;
  border-radius: var(--mfd-radius-pill);
  display: inline-block;
  height: var(--mfd-icon-size-sm);
  width: var(--mfd-icon-size-sm);
}

.mfd-select__positioner {
  z-index: 20;
}

.mfd-select__popup {
  background: var(--mfd-color-bg-surface);
  border: 1px solid var(--mfd-color-border-subtle);
  border-radius: var(--mfd-radius-control);
  box-shadow: var(--mfd-elevation-overlay);
  color: var(--mfd-color-text-primary);
  min-width: var(--anchor-width);
  padding: var(--mfd-space-stack-xs);
}

.mfd-select__item {
  align-items: center;
  border-radius: var(--mfd-radius-control);
  cursor: pointer;
  display: flex;
  gap: var(--mfd-space-inline-md);
  justify-content: space-between;
  min-height: var(--mfd-size-hit-target-minimum);
  padding: var(--mfd-space-stack-sm) var(--mfd-space-inline-sm);
  outline: none;
}

.mfd-select__item[data-highlighted] {
  background: var(--mfd-color-bg-subtle);
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: -2px;
}

.mfd-select__item[data-disabled] {
  cursor: not-allowed;
  opacity: 0.55;
}

.mfd-select__item-indicator {
  color: var(--mfd-color-accent-text);
  font-weight: var(--mfd-typography-label-font-weight);
}

@media (prefers-reduced-motion: reduce) {
  .mfd-select__trigger,
  .mfd-select__item {
    transition: none;
  }

  .mfd-select__spinner {
    animation-duration: 1.5s;
  }
}

@keyframes mfd-select-spin {
  to {
    transform: rotate(1turn);
  }
}
